#include <iostream>
#include <string>

int main() {
    std::string s;
    std::getline(std::cin, s);
    for (size_t i = 1; i + 1 < s.length() - 1; ++i) {
        if (s[i] == 'a' && s[i + 1] == 't') {
            s.replace(i, 2, "@");
            break;
        }
    }
    size_t i = 1;
    while (i + 2 < s.length() - 1) {
        if (s[i] == 'd' && s[i + 1] == 'o' && s[i + 2] == 't') {
            s.replace(i, 3, ".");
        }
        ++i;
    }
    std::cout << s << std::endl;
    return 0;
}
